(()=>{
const key='shee-collections-v1';
function read(){const data=structuredClone(Account.get('collections',[{id:'favorite',name:'Favorite',questions:[]}]));if(!data.some(c=>c.id==='favorite'))data.unshift({id:'favorite',name:'Favorite',questions:[]});return data;}
async function save(data){await Account.save('collections',data);window.dispatchEvent(new Event('collections-changed'));}
async function create(name){name=name.trim();if(!name||name.length>80)throw Error('Enter a collection name of 1–80 characters.');const data=read();if(data.some(x=>x.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw Error('A collection with this name already exists.');const c={id:crypto.randomUUID(),name,questions:[]};data.push(c);await save(data);return c.id;}
async function toggle(id,qid,on){const data=read(),c=data.find(x=>x.id===id);if(!c)throw Error('Collection no longer exists.');c.questions=on?[...new Set([...c.questions,qid])]:c.questions.filter(x=>x!==qid);await save(data);}
function contains(id,qid){if(!id)return true;return !!read().find(x=>x.id===id)?.questions.includes(qid);}
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(q){const box=document.getElementById('question-collections');if(!box)return;try{const data=read();box.innerHTML=`<details><summary>Save to collections${data.some(c=>c.questions.includes(q.id))?' · Saved':''}</summary><p class="subtle">Select one or more collections. Saved to your account.</p><div class="collection-list">${data.map(c=>`<label><input type="checkbox" data-collection="${esc(c.id)}" ${c.questions.includes(q.id)?'checked':''}> ${esc(c.name)}</label>`).join('')}</div><form id="create-collection"><label for="collection-name">New collection</label><div class="collection-create"><input id="collection-name" maxlength="80" placeholder="e.g. Need revision" required><button class="secondary">Create and add</button></div></form><p role="status" id="collection-state"></p><a href="/sets.html?v=accounts1">Review your collections</a></details>`;box.querySelectorAll('[data-collection]').forEach(input=>input.onchange=async()=>{try{await toggle(input.dataset.collection,q.id,input.checked);box.querySelector('summary').textContent='Save to collections'+(read().some(c=>c.questions.includes(q.id))?' · Saved':'');document.getElementById('collection-state').textContent='Collection updated.'}catch(e){input.checked=!input.checked;document.getElementById('collection-state').textContent=e.message}});document.getElementById('create-collection').onsubmit=async e=>{e.preventDefault();try{const id=await create(document.getElementById('collection-name').value);await toggle(id,q.id,true);render(q);box.querySelector('details').open=true;document.getElementById('collection-state').textContent='Created and question added.'}catch(err){document.getElementById('collection-state').textContent=err.message}}}catch(e){box.textContent=e.message}}
window.Collections={read,create,toggle,contains,render};
})();
